              '    Justification: Health, punctuality, emissions reduction         clauses\n'
              '    Operational Requirements: Secure lockers & changing             Accurate punctuation: '
              'semi-colons, commas in lists &\n'
              '    facilities                                                      apostrophes\n'
              '    Next steps: Requesting review at next board meeting &\n'
