WORKBOOK_L2_TASKS = [{'format_idx': 1, 'format_name': 'Article', 'question_num': 1, 'marks': 21, 'word_count': '250–350 words', 'topic': 'The Rise of Cashless High Streets: Convenience or Financial Exclusion?', 'audience': 'Readers of a regional current affairs magazine (The Metro Observer)', 'specialist_words': ['contactless', 'financial inclusion', 'vulnerable citizens', 'infrastructure', 'digital divide', 'transaction', 'autonomy', 'budgeting', 'accessibility', 'consumer choice'], 'stimulus': "The Metro Observer — Feature Article Brief: Across the UK, an increasing number of cafés, car parks, and high street retailers are displaying 'Card & Contactless Only' signs. While businesses argue that handling physical cash is costly and slow, consumer groups warn that millions of older residents, low-income households, and people on strict cash budgets are being locked out of everyday life.", 'bullets': ['Explain why many high street businesses and transport operators prefer cashless payment systems.', 'Analyse the negative impact of a cashless society on vulnerable groups, budgeting, and privacy.', 'Propose balanced solutions (such as mandatory cash acceptance for essential goods and banking hubs).', 'End with a persuasive conclusion and call to action for readers and local businesses.'], 'strategy': 'Use a compelling headline, byline, subheadings, balanced counter-arguments, and rhetorical questions.'}, {'format_idx': 1, 'format_name': 'Article', 'question_num': 2, 'marks': 21, 'word_count': '250–350 words', 'topic': 'Why Every Secondary School and College Should Teach Practical Financial Literacy', 'audience': 'Parents, educators, and adult learners reading an education journal', 'specialist_words': ['curriculum', 'compound interest', 'credit score', 'taxation', 'mortgages', 'indebtedness', 'empowerment', 'resilience', 'statutory', 'payslip'], 'stimulus': 'Education Today — Guest Column Brief: A recent national survey revealed that 68% of young adults leave education without understanding how income tax, student loans, overdraft interest, or household energy tariffs work. Campaigners are calling for practical money management to become a compulsory weekly subject.', 'bullets': ['Highlight the real-world financial challenges faced by young adults entering work or independent living.', 'Detail the essential topics that should be taught (decoding payslips, credit scores, budgeting, and avoiding high-interest debt).', 'Address the counter-argument that school timetables are already overcrowded.', 'Conclude with a strong call to action urging curriculum reform.'], 'strategy': 'Structure your article with a bold headline, byline, clear thematic subheadings, and persuasive evidence.'}, {'format_idx': 2, 'format_name': 'Email (Workplace)', 'question_num': 1, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Proposing a Cross-Departmental Job Shadowing Programme', 'audience': 'Operations Director (Ms Helen Vance) at your company', 'specialist_words': ['collaboration', 'silos', 'cross-training', 'operational', 'retention', 'empathy', 'productivity', 'initiative', 'workflow', 'pilot scheme'], 'stimulus': "Internal Staff Survey Finding: Recent feedback shows that customer service, logistics, and finance teams often misunderstand each other's daily pressures, leading to delays when resolving client queries. You want to propose a voluntary one-day-per-quarter Job Shadowing Scheme.", 'bullets': ['Explain the current communication gaps between departments and how they affect customer service.', 'Outline how a one-day quarterly job shadowing programme would work without disrupting daily targets.', 'Highlight the benefits for staff morale, operational resilience, and faster problem-solving.', 'Request a brief meeting next week to discuss launching a four-week pilot.'], 'strategy': 'Include a clear To/From/Subject header, formal salutation, concise paragraphs, and professional sign-off.'}, {'format_idx': 2, 'format_name': 'Email (Workplace)', 'question_num': 2, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Updating Conference Venue Requirements & Dietary Arrangements', 'audience': 'Events Manager (Mr Marcus Sterling) at the Grand Midland Hotel', 'specialist_words': ['itinerary', 'delegates', 'allergens', 'accessibility', 'audio-visual', 'breakout rooms', 'confirmation', 'catering', 'lectern', 'contingency'], 'stimulus': 'Booking Update Note: Your company is hosting its Annual Regional Training Day at the Grand Midland Hotel on Friday 20 November (Booking Ref: GM-8841). Confirmed attendance has risen from 85 to 115 delegates, requiring a larger main hall, roving microphones, and updated dietary catering.', 'bullets': ['Reference the booking number and confirm the increased delegate count from 85 to 115 attendees.', 'Specify the updated audio-visual and room layout requirements (theatre seating, two roving microphones, and step-free stage access).', 'Detail the confirmed dietary requirements (14 vegan, 9 gluten-free, and 3 severe nut allergies).', 'Request an updated itemised invoice and confirmation by Wednesday at 5:00pm.'], 'strategy': 'Use a precise Subject line with the booking reference, bulleted specifications, and polite business register.'}, {'format_idx': 3, 'format_name': 'Formal Letter', 'question_num': 1, 'marks': 21, 'word_count': '250–350 words', 'topic': 'Disputing an Inaccurate Commercial Smart Meter Energy Bill', 'audience': 'Billing Disputes Manager at Sovereign Business Energy Ltd, Manchester M1 4BT', 'specialist_words': ['discrepancy', 'estimated reading', 'tariff', 'direct debit', 'recalculation', 'ombudsman', 'audit', 'meter serial', 'reimbursement', 'rectification'], 'stimulus': "Account Notice: You manage 'Oakwood Print & Design Studio' (Unit 4, Station Approach, Bristol BS1 6QF). Last month, Sovereign Business Energy installed a smart meter (Ref: SM-99204) but yesterday issued an automated quarterly bill for £4,820—more than four times your normal £1,100 usage—based on an erroneous reading.", 'bullets': ['State your account reference, meter serial number, and the exact discrepancy between your normal £1,100 bill and the £4,820 charge.', 'Explain the evidence you have gathered (photographed meter readings and weekend closure logs).', 'Demand an immediate freeze on the disputed direct debit collection and a technical meter inspection.', 'Set a 14-day deadline for a revised invoice before escalating the case to the Energy Ombudsman.'], 'strategy': 'Include full sender and recipient addresses, date, formal salutation, RE: subject line, and matching sign-off.'}, {'format_idx': 3, 'format_name': 'Formal Letter', 'question_num': 2, 'marks': 21, 'word_count': '250–350 words', 'topic': 'Job Application for Regional Logistics & Fleet Coordinator', 'audience': 'HR Recruitment Director, Mrs Clare Henderson, TransNational Freight Ltd, Leeds LS1 5DL', 'specialist_words': ['route optimisation', 'compliance', 'tachograph', 'dispatch', 'supply chain', 'supervisory', 'fuel efficiency', 'key performance', 'health and safety', 'qualification'], 'stimulus': 'Vacancy Advertisement: TransNational Freight Ltd seeks an experienced Regional Logistics & Fleet Coordinator (Ref: LFC-209) to oversee 35 delivery drivers, improve on-time delivery metrics, and reduce fleet fuel emissions across the Northern distribution hub.', 'bullets': ['State the role and reference number you are applying for and summarise your current transport coordination experience.', 'Provide concrete examples of how you improved delivery punctuality and reduced fuel or maintenance costs in a previous role.', 'Demonstrate your knowledge of driver hour regulations, health and safety compliance, and team leadership.', 'Conclude professionally by confirming your availability for interview and enclosing your CV.'], 'strategy': "Use formal business letter conventions, persuasive evidence of achievements, and 'Yours sincerely,'."}, {'format_idx': 4, 'format_name': 'Report', 'question_num': 1, 'marks': 21, 'word_count': '250–350 words', 'topic': 'Feasibility Report on Transitioning the Delivery Fleet to Electric Vans', 'audience': 'Board of Directors at MetroFresh Commercial Catering', 'specialist_words': ['decarbonisation', 'capital expenditure', 'charging infrastructure', 'payload', 'operating costs', 'clean air zone', 'grant funding', 'feasibility', 'depreciation', 'phased'], 'stimulus': "Executive Brief: MetroFresh operates 20 diesel refrigerated delivery vans making daily urban deliveries. With the city's Clean Air Zone introducing a £12.50 daily charge for older diesel vans next April, the Board requested a feasibility report on switching to electric vans.", 'bullets': ['State the purpose of the report and summarise the financial impact of the upcoming Clean Air Zone charges.', 'Present key findings from the 4-week trial of two electric vans (62% lower fuel/charging costs, 140-mile urban range, overnight depot charging constraints).', 'Provide three costed, practical recommendations for a phased transition over 18 months.'], 'strategy': 'Use a formal To/From/Date/Subject report header, numbered subheadings (1. Introduction, 2. Findings, 3. Recommendations), and objective register.'}, {'format_idx': 4, 'format_name': 'Report', 'question_num': 2, 'marks': 21, 'word_count': '250–350 words', 'topic': 'Evaluation Report on New Staff Induction & First-Year Retention', 'audience': 'Senior Management Team at Horizon Contact Services', 'specialist_words': ['onboarding', 'attrition', 'mentorship', 'probation', 'competency', 'benchmark', 'shadowing', 'feedback', 'structured', 'retention'], 'stimulus': 'HR Audit Brief: Over the past year, 28% of new customer advisers left Horizon Contact Services within their first 12 weeks. Exit interviews revealed that new starters felt overwhelmed by the software systems and lacked buddy support after week one.', 'bullets': ['Outline the background and cost implications of the 28% early staff turnover rate.', 'Analyse the main weaknesses identified in exit interviews and staff questionnaires.', 'Recommend three structured improvements to the onboarding and mentorship programme.'], 'strategy': 'Organise with clear numbered subheadings, quantitative evidence, and bulleted action points.'}, {'format_idx': 5, 'format_name': 'Incident Report', 'question_num': 1, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Chemical Cleaning Solvent Spill in Commercial Catering Kitchen (COSHH)', 'audience': 'Regional Health & Safety Compliance Officer', 'specialist_words': ['corrosive', 'ventilation', 'containment', 'COSHH', 'personal protective', 'neutralising', 'evacuation', 'eyewash', 'protocol', 'hazardous'], 'stimulus': "Incident Log Note: On Wednesday 21 October at 14:35 in the Central Preparation Kitchen, a 5-litre container of concentrated oven degreaser split while being lifted from a high shelf by kitchen assistant Liam O'Connor. Fumes caused mild respiratory irritation and splashes reached his forearm.", 'bullets': ['Record the exact date, time, location, personnel involved, and chemical substance.', 'Describe the sequence of events objectively and the immediate first aid and spill containment actions taken.', 'Identify the root storage failure (heavy chemical containers stored above head height without PPE).', 'Specify mandatory preventative actions to ensure full COSHH compliance.'], 'strategy': 'Use an official Incident Report header block, objective factual language, chronological order, and corrective actions.'}, {'format_idx': 5, 'format_name': 'Incident Report', 'question_num': 2, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Automated Packaging Conveyor Jam & Guard Interlock Near-Miss', 'audience': 'Plant Engineering & Safety Manager', 'specialist_words': ['interlock', 'emergency stop', 'isolation', 'lockout', 'near-miss', 'mechanical', 'guarding', 'maintenance', 'supervisor', 'inspection'], 'stimulus': 'Shift Safety Note: On Thursday 22 October at 07:50 on Packing Line 2, cardboard cartons jammed inside the heat-shrink tunnel. Line operator Priya Sharma reached towards the intake rollers before pressing the emergency stop; fortunately, the supervisor triggered the cut-off switch in time.', 'bullets': ['State the precise time, location, machinery identification, and staff members involved.', "Give a factual, chronological account of the jam, the operator's action, and the supervisor's intervention.", 'Explain why the safety guard interlock sensor failed to halt the belt automatically.', 'Recommend immediate engineering lock-off checks and refresher Lockout/Tagout training.'], 'strategy': 'Maintain a strictly neutral, factual register with clear headings and preventative recommendations.'}, {'format_idx': 6, 'format_name': 'Advice Leaflet', 'question_num': 1, 'marks': 21, 'word_count': '250–350 words', 'topic': 'Protecting Personal Data & Avoiding Phishing Scams When Working Remotely', 'audience': 'Company employees working from home or travelling', 'specialist_words': ['multi-factor', 'encryption', 'phishing', 'unsecured', 'credentials', 'cybersecurity', 'verification', 'confidential', 'vigilance', 'breach'], 'stimulus': 'IT Security Brief: With 60% of staff now working remotely two days a week, fraudulent emails impersonating bank and courier services have doubled. Produce a clear, authoritative staff advice leaflet on staying cyber-secure outside the office.', 'bullets': ['Use a bold leaflet title and engaging introduction explaining why remote workers are targeted.', 'Provide clear subheadings and imperative bullet points on spotting phishing links and securing home Wi-Fi.', 'Explain rules for handling confidential client documents in public spaces (trains, cafés).', "Include a highlighted 'Report a Suspicious Email Immediately' emergency IT helpdesk box."], 'strategy': 'Use a bold masthead title, subheadings, parallel imperative bullet points, and a callout contact box.'}, {'format_idx': 6, 'format_name': 'Advice Leaflet', 'question_num': 2, 'marks': 21, 'word_count': '250–350 words', 'topic': 'Preparing for Competency-Based Job Interviews: A Practical Candidate Guide', 'audience': 'Jobseekers and career changers attending a regional employment hub', 'specialist_words': ['competency', 'articulate', 'body language', 'preparation', 'proactive', 'evidence', 'punctuality', 'portfolio', 'rapport', 'follow-up'], 'stimulus': 'Careers Hub Brief: Many capable candidates underperform in formal interviews because they give vague answers rather than structured examples. Write a practical advice leaflet explaining how to research employers and use the STAR method (Situation, Task, Action, Result).', 'bullets': ['Write an encouraging title and opening paragraph explaining what employers look for in competency interviews.', 'Explain step by step how to structure answers using the STAR method (Situation, Task, Action, Result).', 'Provide a bulleted checklist on pre-interview research, professional dress, and questions to ask the panel.', 'Conclude with a support box detailing free mock interview bookings at the Careers Hub.'], 'strategy': 'Break complex advice into digestible subheadings, bulleted checklists, and encouraging direct address.'}, {'format_idx': 7, 'format_name': 'Review', 'question_num': 1, 'marks': 15, 'word_count': '200–250 words', 'topic': "Review of 'EcoStitch' Sustainable Workwear & Uniform Range", 'audience': 'Procurement managers reading Trade & Hospitality Monthly', 'specialist_words': ['durability', 'recycled', 'breathable', 'stitching', 'cost-effective', 'ethical', 'shrinkage', 'garment', 'aesthetic', 'verdict'], 'stimulus': "Product Trial Note: Your catering and facilities team trialled the new 'EcoStitch' recycled poly-cotton workwear range for six weeks. The jackets and tunics were breathable, stain-resistant, and popular with staff, though sizing ran small and delivery took three weeks.", 'bullets': ['Include an engaging review headline, star rating, and overview of the six-week workplace trial.', 'Evaluate the fabric quality, comfort during long shifts, and industrial wash durability.', 'Critique the sizing inaccuracies and slow three-week dispatch turnaround.', 'Deliver a balanced final verdict and state which businesses would benefit most from this range.'], 'strategy': 'Use an evaluative headline, star rating, balanced pros and cons, and a decisive recommendation.'}, {'format_idx': 7, 'format_name': 'Review', 'question_num': 2, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Review of the Annual Regional Careers & Skills Expo at City Arena', 'audience': 'Readers of a regional training and business website', 'specialist_words': ['exhibitors', 'interactive', 'networking', 'acoustics', 'keynote', 'accessibility', 'seminars', 'organisation', 'worthwhile', 'venue'], 'stimulus': "Event Note: You attended Saturday's Regional Careers & Skills Expo at City Arena. Over 90 employers offered live CV clinics and practical trade demonstrations, but poorly signposted seminar rooms and overpriced parking frustrated many attendees.", 'bullets': ['Give your review a clear title, rating out of 5 stars, and lively opening impression of the event.', 'Praise the variety of employer stands, interactive trade simulators, and one-to-one CV clinics.', 'Highlight organizational drawbacks (poor seminar room signage, crowded aisles, and £15 car park fee).', "Conclude with a clear recommendation for next year's attendees and organisers."], 'strategy': 'Balance specific praise with constructive criticism using vivid evaluative adjectives.'}, {'format_idx': 8, 'format_name': 'Online Feedback Form', 'question_num': 1, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Public Consultation Feedback on Proposed Town Centre Clean Air Zone', 'audience': 'City Council Highways & Environment Committee', 'specialist_words': ['emissions', 'air quality', 'exemptions', 'small businesses', 'congestion', 'public transport', 'subsidy', 'phased', 'consultation', 'residents'], 'stimulus': 'Council Consultation Portal: The City Council is consulting residents and local traders on plans to introduce a £10 daily charge for older commercial vans and non-compliant cars entering the ring road from January.', 'bullets': ['Complete the respondent details, stakeholder category, and overall support rating clearly.', 'Acknowledge the health benefits of reducing nitrogen dioxide pollution near schools and clinics.', 'Explain the financial strain the £10 daily charge will place on self-employed tradespeople and care workers.', 'Propose fair amendments (a 12-month grace period for sole traders and expanded park-and-ride frequency).'], 'strategy': 'Complete all form metadata fields and write structured, persuasive paragraphs in the response sections.'}, {'format_idx': 8, 'format_name': 'Online Feedback Form', 'question_num': 2, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Customer Service Feedback on Business Broadband Outage & Missed Engineer Visit', 'audience': 'Customer Resolution Team at HyperFibre Business Telecoms', 'specialist_words': ['outage', 'service level agreement', 'downtime', 'compensation', 'diagnostics', 'escalation', 'unacceptable', 'telecommunications', 'revenue', 'reliability'], 'stimulus': 'Service Ticket #HF-7712: Your high-street accountancy office lost fibre broadband for 36 hours on Monday and Tuesday. Despite an automated text confirming an engineer between 08:00 and 12:00 on Tuesday, nobody arrived until Wednesday morning.', 'bullets': ['Fill in the Account Number, Service Ticket Reference, Date of Outage, and Satisfaction Score (1/5).', 'Detail the 36-hour loss of connectivity and the commercial disruption caused to client tax filings.', 'Complain about the missed Tuesday morning engineer appointment and lack of proactive updates.', 'Specify the resolution required: statutory SLA compensation credit and a root-cause line report.'], 'strategy': 'Keep your tone firm, factual, and professional while citing exact dates, times, and reference numbers.'}, {'format_idx': 9, 'format_name': 'Online Forum / Blog Post', 'question_num': 1, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Should Employers Have the Right to Contact Staff Outside Working Hours?', 'audience': "Members of the 'UK Workplace & Careers' online discussion forum", 'specialist_words': ['boundaries', 'burnout', 'right to disconnect', 'productivity', 'work-life balance', 'notifications', 'autonomous', 'wellbeing', 'expectations', 'culture'], 'stimulus': "Forum Thread by @ManagerMike_UK: 'In today's fast-paced economy, answering a quick evening email takes two minutes and keeps projects moving. Banning out-of-hours messages is unrealistic.' Reply to this thread with your perspective.", 'bullets': ["Include a clear forum username/timestamp header and respond directly to @ManagerMike_UK's comment.", 'Explain how constant evening and weekend notifications contribute to staff burnout and unpaid overtime.', "Acknowledge genuine emergencies while arguing for clear 'right to disconnect' workplace policies.", 'End with an engaging question inviting other forum members to share their workplace rules.'], 'strategy': 'Adopt a lively, semi-formal conversational register while maintaining Band 4 punctuation and vocabulary.'}, {'format_idx': 9, 'format_name': 'Online Forum / Blog Post', 'question_num': 2, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Blog Post: How Retraining as an Adult Learner Transformed My Career Confidence', 'audience': 'Adult learners reading a lifelong learning and careers blog', 'specialist_words': ['retraining', 'transferable skills', 'resilience', 'qualification', 'imposter syndrome', 'flexibility', 'progression', 'milestone', 'mentoring', 'ambition'], 'stimulus': 'Guest Blog Brief: Adult Learning Week is inviting blog posts from people who returned to study or completed professional qualifications while juggling work and family commitments.', 'bullets': ['Create an inspiring blog post title, author line, and relatable opening hook about returning to education.', 'Describe the initial challenges of balancing evening study with work and how you overcame self-doubt.', 'Explain the practical career benefits and transferable skills gained from achieving your qualification.', 'Finish with encouraging advice and a question prompting readers to share their learning goals in the comments.'], 'strategy': 'Combine personal reflection with structured paragraphs, varied sentence openers, and direct reader engagement.'}, {'format_idx': 10, 'format_name': 'Newsletter', 'question_num': 1, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Quarterly Staff Innovation & Employee Recognition Newsletter', 'audience': "All employees across Apex Engineering's three regional sites", 'specialist_words': ['innovation', 'milestone', 'excellence', 'sustainability', 'nomination', 'accreditation', 'collaborative', 'efficiency', 'initiative', 'celebrate'], 'stimulus': "Internal Communications Brief: Compile the Autumn edition of the 'Apex Pulse' staff newsletter celebrating the warehouse team's zero-waste award, announcing the new Staff Suggestion Bonus Scheme (£250 for efficiency ideas), and inviting nominations for Employee of the Year.", 'bullets': ['Include a clear newsletter masthead banner, issue number, and upbeat editorial welcome.', 'Congratulate the logistics team on achieving Gold Zero-Waste Accreditation and cutting packaging waste by 40%.', 'Explain how staff can submit ideas to the new £250 Innovation Bonus Scheme.', "Include a 'Key Dates & Nominations' box with the deadline for Employee of the Year entries."], 'strategy': 'Use a masthead banner, energetic subheadings, celebratory yet professional tone, and a dates callout box.'}, {'format_idx': 10, 'format_name': 'Newsletter', 'question_num': 2, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Regional Chamber of Commerce Small Business Networking Newsletter', 'audience': 'Local business owners, freelancers, and entrepreneurs', 'specialist_words': ['entrepreneurship', 'networking', 'procurement', 'grants', 'mentorship', 'workshop', 'digital marketing', 'registration', 'growth', 'thriving'], 'stimulus': "Chamber Brief: Write the monthly 'Westside Business Connect' newsletter announcing the new Council Small Business Energy Grant (up to £2,500), recapping last month's record networking breakfast, and promoting next Thursday's free Digital Marketing Workshop.", 'bullets': ['Create a professional newsletter masthead and welcoming introduction for local business members.', 'Detail how independent businesses can apply for the £2,500 Energy Efficiency Grant before 30 November.', 'Promote the upcoming Digital Marketing & SEO Workshop (Thursday 19 November, 5:30pm at Town Hall).', 'Conclude with booking contact details and a call for guest speakers.'], 'strategy': 'Organise with clear section subheadings, precise dates and grant figures, and a call-to-action footer.'}, {'format_idx': 11, 'format_name': 'Diary / Reflective Entry', 'question_num': 1, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Reflective Log: De-escalating a Complex Customer Complaint on the Service Desk', 'audience': 'Professional development portfolio and line manager review', 'specialist_words': ['de-escalation', 'empathy', 'active listening', 'resolution', 'composure', 'protocol', 'accountability', 'rapport', 'reflection', 'competence'], 'stimulus': 'CPD Log Prompt: Record a reflective entry for your Customer Service Level 2 portfolio describing a challenging shift where an angry client demanded an immediate refund for a delayed bespoke order, how you calmed the situation, and what you learned.', 'bullets': ['Include a dated reflective log header (Date, Role, Department, and Competency Focus).', 'Describe the situation and your initial response when faced with the frustrated customer.', 'Evaluate how using active listening, empathy, and clear options successfully resolved the dispute.', 'Set two specific professional development targets for handling high-pressure escalations in future.'], 'strategy': "Write in thoughtful first-person ('I') using analytical reflection (Action -> Impact -> Next Steps)."}, {'format_idx': 11, 'format_name': 'Diary / Reflective Entry', 'question_num': 2, 'marks': 15, 'word_count': '200–250 words', 'topic': 'Reflective Log: Completing Workplace First Aid & Defibrillator Certification', 'audience': 'Health & Safety Training Coordinator and personal CPD record', 'specialist_words': ['resuscitation', 'defibrillator', 'assessment', 'emergency', 'confidence', 'procedure', 'simulation', 'First Aider', 'responsibilities', 'refresher'], 'stimulus': 'Training Log Prompt: You have just completed a two-day Emergency First Aid at Work course, including practical CPR and Automated External Defibrillator (AED) drills. Write a reflective entry evaluating your learning and workplace readiness.', 'bullets': ['Include a structured log header with the date, course title, and trainer details.', 'Reflect on which practical scenarios (primary survey, recovery position, AED pads) went well and what felt challenging.', 'Explain how the training changed your understanding of workplace emergency preparedness.', 'Outline the immediate actions you will take back at work (auditing the first aid kit and checking defibrillator signage).'], 'strategy': 'Balance honest personal reflection with precise technical terminology and concrete workplace actions.'}, {'format_idx': 12, 'format_name': 'Speech / Presentation Talk', 'question_num': 1, 'marks': 21, 'word_count': '250–350 words', 'topic': 'Staff Briefing Speech: Introducing a New Flexible Shift-Bidding System', 'audience': '40 operations and customer support staff at a Monday morning briefing', 'specialist_words': ['flexibility', 'transparency', 'work-life balance', 'fairness', 'allocation', 'roster', 'consultation', 'portal', 'transition', 'feedback'], 'stimulus': "Briefing Note: Following staff complaints that monthly shift rotas were issued too late and favoured certain teams, you are introducing a fair digital Shift-Bidding Portal next month that gives everyone four weeks' notice and priority preferences.", 'bullets': ['Open with an engaging greeting and acknowledge staff feedback regarding the old rota system.', 'Explain clearly how the new digital Shift-Bidding Portal works and ensures fair weekend rotation.', 'Reassure staff who may worry about using the app by outlining drop-in training sessions this week.', 'Conclude with an upbeat summary and invite questions from the floor.'], 'strategy': "Use direct spoken address ('you', 'we'), rhetorical questions, clear verbal signposts, and a warm closing."}, {'format_idx': 12, 'format_name': 'Speech / Presentation Talk', 'question_num': 2, 'marks': 21, 'word_count': '250–350 words', 'topic': 'Council Planning Committee Speech: Advocating for Safe Cycle Lanes to the Business Park', 'audience': 'Local Councillors and Highways Officers at a public planning meeting', 'specialist_words': ['infrastructure', 'segregated', 'commuters', 'congestion', 'sustainability', 'safety', 'investment', 'collisions', 'economic', 'pedestrians'], 'stimulus': 'Public Speaker Brief: Over 1,200 people work at Riverside Business Park, but the narrow approach road has no cycle lane or street lighting. Three cyclists have been injured in minor collisions this year. You have 4 minutes to address the Council Planning Committee.', 'bullets': ['Greet the Committee Chair and councillors formally and state who you represent.', 'Present compelling evidence of the current safety hazards and recent collisions on the approach road.', 'Explain how a segregated, lit cycle path will cut rush-hour congestion, reduce pollution, and boost staff health.', 'Deliver a memorable closing appeal urging the committee to approve the highways funding tonight.'], 'strategy': 'Combine authoritative facts and statistics with persuasive DAFOREST techniques and spoken signposting.'}]

WORKBOOK_L1_TASKS = [{'format_idx': 1, 'format_name': 'Article', 'question_num': 1, 'marks': 21, 'word_count': '150–250 words', 'topic': 'Protecting Local Wildlife & Creating Nature-Friendly Gardens in Our Town', 'audience': 'Local residents reading the Oakwood Community Magazine', 'specialist_words': ['wildlife', 'hedgehogs', 'wildflowers', 'bird feeders', 'nature', 'shelters', 'pollinators', 'environment', 'gardens', 'community'], 'stimulus': 'Magazine Notice: Our local wildlife group wants to encourage residents with gardens, balconies, or shared yards to help birds, bees, and hedgehogs thrive this spring. Write a friendly article full of simple, low-cost tips.', 'bullets': ['Include a catchy headline, your name (byline), and an engaging opening question.', 'Explain why local birds, bees, and hedgehogs need help in busy towns.', 'Give three easy, low-cost ways residents can help (planting wildflowers, leaving water bowls, making a small fence gap for hedgehogs).', 'End with an encouraging call to action inviting readers to pick up free wildflower seeds at the library.'], 'strategy': 'Use a clear headline, byline, two short subheadings, and friendly everyday language.'}, {'format_idx': 1, 'format_name': 'Article', 'question_num': 2, 'marks': 21, 'word_count': '150–250 words', 'topic': 'Why Volunteering in Your Neighbourhood Is Great for Confidence and New Skills', 'audience': 'Adult learners and local residents reading a town website', 'specialist_words': ['volunteering', 'confidence', 'teamwork', 'experience', 'neighbours', 'friendship', 'rewarding', 'skills', 'community', 'flexible'], 'stimulus': 'Website Feature Brief: Many people want to build their CV, meet new friends, or help their local neighbourhood, but think volunteering takes too much time. Write an upbeat article showing that even two hours a week makes a big difference.', 'bullets': ['Write a welcoming headline and opening paragraph about what volunteering means.', 'Give examples of local ways to help (charity shops, food banks, park clean-ups, or library reading buddies).', 'Explain how volunteering builds confidence, teamwork, and practical work experience for your CV.', 'Finish by telling readers how to sign up at the Friday Volunteering Fair in the Town Hall.'], 'strategy': "Use subheadings, linking words ('In addition', 'Because', 'However'), and a positive closing sentence."}, {'format_idx': 2, 'format_name': 'Email (Workplace)', 'question_num': 1, 'marks': 15, 'word_count': '100–180 words', 'topic': 'Suggesting Simple Energy-Saving Steps in the Office', 'audience': 'Your Office Manager, Mrs Sarah Jenkins', 'specialist_words': ['electricity', 'monitors', 'heating', 'standby', 'recycling', 'switches', 'energy', 'saving', 'posters', 'colleagues'], 'stimulus': 'Workplace Note: You noticed that computer monitors, photocopiers, and meeting room lights are often left switched on overnight in your office. Mrs Sarah Jenkins has asked staff for simple ideas to cut electricity waste.', 'bullets': ["Write a clear To: and Subject: line and a polite greeting ('Dear Mrs Jenkins,').", 'Describe the energy waste you noticed at the end of the working day.', "Suggest two practical solutions (putting 'Switch Off' reminder stickers by light switches and setting computers to sleep mode).", 'Offer to help put up reminder signs this Friday and sign off politely.'], 'strategy': "Include To/Subject headers, polite workplace tone, clear paragraphs, and 'Kind regards,'."}, {'format_idx': 2, 'format_name': 'Email (Workplace)', 'question_num': 2, 'marks': 15, 'word_count': '100–180 words', 'topic': 'Organising a Sunday Charity Walk & Picnic with Friends', 'audience': 'Your walking group friends', 'specialist_words': ['sponsored', 'route', 'waterproof', 'picnic', 'train station', 'footwear', 'donations', 'weather', 'excited', 'confirm'], 'stimulus': "Event Note: You are organising a 5-mile charity walk along the River Valley Trail next Sunday 15 November to raise money for the local children's hospice. Email your friends with the meeting details.", 'bullets': ["Include a clear Subject line and a warm, friendly greeting ('Hi everyone,').", 'Give the exact date, meeting time (9:30am outside Central Station), and 5-mile river route.', 'Remind everyone what to bring (walking shoes, waterproof jacket, water bottle, and packed lunch).', 'Ask friends to reply by Thursday to confirm if they are coming.'], 'strategy': 'Use a warm, friendly tone while keeping full sentences, capital letters, and accurate punctuation.'}, {'format_idx': 3, 'format_name': 'Formal Letter', 'question_num': 1, 'marks': 21, 'word_count': '150–250 words', 'topic': 'Complaining to the Bus Company About Late Morning Buses on Route 18', 'audience': 'Customer Relations Manager, CityLink Buses, 12 Station Road, Bristol BS1 3AA', 'specialist_words': ['timetable', 'delayed', 'passengers', 'punctual', 'overcrowded', 'commuters', 'reliable', 'apology', 'shelter', 'schedule'], 'stimulus': 'Passenger Note: You catch the 8:15am Route 18 bus from Highfield Stop to get to work for 9:00am. Over the past two weeks, the 8:15am bus has been more than 25 minutes late four times, and twice it drove straight past waiting passengers because it was full.', 'bullets': ["Include your address and today's date in the top-right corner, and the bus company's address on the left.", 'Explain which bus route and time you use (8:15am Route 18 from Highfield Stop) and what has gone wrong.', 'Describe how the delays have affected you (arriving late for work and paying for expensive taxis).', 'Ask the manager to put a larger double-decker bus on the 8:15am route and refund your weekly bus pass.'], 'strategy': "Use full formal letter layout, polite but firm tone, and 'Yours faithfully,'."}, {'format_idx': 3, 'format_name': 'Formal Letter', 'question_num': 2, 'marks': 21, 'word_count': '150–250 words', 'topic': 'Inviting a Relative to a Special Family Birthday Meal', 'audience': 'Your Aunt Clara, who lives in another town', 'specialist_words': ['celebration', 'surprise', 'restaurant', 'transport', 'spare room', 'menu', 'saturday', 'family', 'memories', 'invitation'], 'stimulus': "Family Note: Next month is your mum's 60th birthday. You are organising a surprise family lunch at 'The Olive Tree Restaurant' on Saturday 21 November at 1:00pm and want to invite your Aunt Clara to stay for the weekend.", 'bullets': ["Put your address and date in the top-right corner and open warmly ('Dear Aunt Clara,').", 'Explain the surprise 60th birthday lunch on Saturday 21 November at 1:00pm at The Olive Tree Restaurant.', 'Offer to pick her up from the train station and let her know she can stay in your spare room on Saturday night.', "Ask her to reply soon with her train time and any food choices, and close warmly ('Best wishes,' or 'Lots of love,')."], 'strategy': 'Use informal letter layout (sender address and date top right only), warm tone, and clear paragraphs.'}, {'format_idx': 4, 'format_name': 'Report', 'question_num': 1, 'marks': 15, 'word_count': '140–200 words', 'topic': 'Report on Staff Break Room Hygiene & Kitchen Appliances', 'audience': 'Workplace Facilities Manager, Mr David Ross', 'specialist_words': ['hygiene', 'refrigerator', 'kettle', 'microwave', 'cleaning', 'rota', 'worktop', 'facilities', 'improvements', 'comfortable'], 'stimulus': 'Workplace Survey: Staff have complained that the workplace break room is untidy, the small fridge is overcrowded, and one of the two kettles is broken. Mr Ross asked you to write a short report with practical suggestions.', 'bullets': ['Include a clear Report Title and a To / From / Date header block.', 'Describe the main problems found in the break room (overcrowded fridge, broken kettle, and unwashed mugs).', 'Give three bulleted recommendations (buying a larger fridge, replacing the faulty kettle, and putting up a weekly cleaning rota).'], 'strategy': "Use clear subheadings ('1. Purpose', '2. Current Problems', '3. Recommendations') and factual language."}, {'format_idx': 4, 'format_name': 'Report', 'question_num': 2, 'marks': 15, 'word_count': '140–200 words', 'topic': 'Report on Weekend Visitor Facilities at Lakeside Nature Reserve', 'audience': 'Parks & Countryside Officer at the Local Council', 'specialist_words': ['footpaths', 'signposts', 'litter bins', 'picnic', 'visitors', 'wheelchair', 'car park', 'muddy', 'wildlife', 'maintenance'], 'stimulus': 'Volunteer Inspection Note: As a volunteer ranger at Lakeside Nature Reserve, you counted over 300 visitors last Sunday. However, the main wooden signpost by the car park is broken, the lakeside path is very muddy for pushchairs, and the two picnic bins were overflowing.', 'bullets': ['Write a factual Report Title and To / From / Date header.', 'Explain what went well (high visitor numbers enjoying the bird hides) and the three problems you recorded.', 'Provide clear bulleted recommendations to repair the signpost, lay gravel on the muddy path, and add larger recycling bins.'], 'strategy': 'Organise your report under numbered subheadings and keep your tone clear and objective.'}, {'format_idx': 5, 'format_name': 'Incident Report', 'question_num': 1, 'marks': 15, 'word_count': '120–180 words', 'topic': 'Damaged Power Cable on Workshop Sander (Near-Miss Safety Report)', 'audience': 'Workshop Health & Safety Supervisor', 'specialist_words': ['damaged', 'cable', 'unplugged', 'warning', 'electrician', 'inspection', 'hazard', 'equipment', 'prevent', 'workshop'], 'stimulus': 'Safety Note: On Tuesday 20 October at 11:10am in Carpentry Workshop B, trainee Ben Carter noticed bare copper wires showing on the power plug of an electric hand sander before switching it on. Nobody was hurt.', 'bullets': ['Fill in the Incident Header (Date, Time, Location, Person Involved, and Reported By).', 'Explain clearly what Ben Carter spotted and how you immediately unplugged the sander and locked it in the repair cupboard.', 'Recommend a weekly safety check of all power tool cables before classes start.'], 'strategy': 'Stick to exact times, names, and facts in time order, and state how to prevent a future accident.'}, {'format_idx': 5, 'format_name': 'Incident Report', 'question_num': 2, 'marks': 15, 'word_count': '120–180 words', 'topic': 'Minor Cut & First Aid Treatment in the Staff Kitchenette', 'audience': 'Store Health & Safety Officer', 'specialist_words': ['first aid', 'plaster', 'antiseptic', 'broken glass', 'gloves', 'sharps bin', 'accident book', 'cut', 'cleaned', 'safe'], 'stimulus': 'Accident Note: On Friday 23 October at 1:20pm in the first-floor staff kitchenette, sales assistant Maya Lin cut her right index finger on a cracked glass tumbler while washing up in the sink.', 'bullets': ['Include the Date, Time, Exact Location, Injured Person, and First Aider name at the top.', 'Describe how the accident happened and the first aid given (cleaning the cut with antiseptic wipe and applying a waterproof plaster).', 'Explain how the broken glass was safely wrapped and disposed of, and recommend checking all staff glassware weekly.'], 'strategy': 'Write clearly in chronological order using calm, factual sentences.'}, {'format_idx': 6, 'format_name': 'Advice Leaflet', 'question_num': 1, 'marks': 21, 'word_count': '150–250 words', 'topic': 'Staying Warm and Cutting Heating Bills at Home This Winter', 'audience': 'Local residents visiting the Community Advice Centre', 'specialist_words': ['thermostat', 'draughts', 'curtains', 'radiators', 'insulation', 'heating', 'temperature', 'warm', 'energy', 'support'], 'stimulus': 'Community Advice Brief: Many households worry about high winter heating bills. Write a clear, helpful advice leaflet giving simple ways to keep heat inside the home and where to get free energy advice.', 'bullets': ['Write a bold Leaflet Title and a short, friendly introduction.', "Use subheadings and bullet points starting with command verbs ('Close curtains at dusk', 'Keep furniture away from radiators', 'Block chilly draughts under doors').", 'Explain how turning the room thermostat down by just 1 degree can save money while keeping rooms comfortable.', "Finish with a 'Where to Get Free Help' box showing the Community Energy Helpline number (0800 555 202)."], 'strategy': 'Use a bold title, clear section subheadings, bulleted tips, and a final help box.'}, {'format_idx': 6, 'format_name': 'Advice Leaflet', 'question_num': 2, 'marks': 21, 'word_count': '150–250 words', 'topic': 'Top Tips for Safe Cycling on Busy Town Roads', 'audience': 'New adult and teenage cyclists in your town', 'specialist_words': ['helmet', 'reflective', 'lights', 'brakes', 'tyres', 'signals', 'cycle lane', 'junctions', 'visible', 'confident'], 'stimulus': 'Road Safety Brief: More residents are cycling to work and college, especially in the darker autumn afternoons. Write an easy-to-read road safety leaflet for new cyclists.', 'bullets': ['Give your leaflet an eye-catching title and positive opening sentence.', 'Include a section on checking your bike before setting off (brakes, tyre pressure, and working front white and rear red lights).', 'Use bullet points to explain safe road habits (wearing a helmet and bright reflective clothing, giving clear hand signals, and never using a phone).', 'Add a final box inviting readers to free Saturday Bike Maintenance Checks at the Town Square.'], 'strategy': 'Organise with subheadings, bossy action-verb bullet points, and a contact/event box.'}, {'format_idx': 7, 'format_name': 'Review', 'question_num': 1, 'marks': 15, 'word_count': '110–170 words', 'topic': 'Review of the Newly Refurbished Starlight Cinema on Market Street', 'audience': 'Local residents reading the town entertainment website', 'specialist_words': ['comfortable', 'reclining', 'screen', 'sound', 'tickets', 'popcorn', 'queues', 'friendly', 'value', 'recommend'], 'stimulus': 'Review Prompt: Last Friday evening you visited the newly reopened Starlight Cinema on Market Street. The heated reclining seats and £6 Tuesday ticket deal were fantastic, though the snack counter queue was slow and popcorn was expensive.', 'bullets': ['Write a catchy Review Title, a star rating (e.g. 4/5 Stars), and when you visited.', 'Describe what you loved about the cinema (comfortable reclining seats, crystal-clear sound, and friendly ticket staff).', 'Mention what could be improved (the 20-minute queue at the snack counter and pricey drinks).', 'End with a clear recommendation telling readers the best day to visit.'], 'strategy': 'Include a title, star rating, balanced positives and negatives, and a final recommendation.'}, {'format_idx': 7, 'format_name': 'Review', 'question_num': 2, 'marks': 15, 'word_count': '110–170 words', 'topic': "Review of a 'StormGuard' Waterproof Winter Walking Jacket", 'audience': 'Shoppers on an outdoor clothing website', 'specialist_words': ['waterproof', 'lightweight', 'hood', 'pockets', 'zip', 'windproof', 'warm', 'sizing', 'durable', 'bargain'], 'stimulus': "Product Review Prompt: You bought a 'StormGuard' Waterproof Walking Jacket (£45) last month and wore it on three rainy weekend walks. It kept you completely dry and has deep zipped pockets, although the sleeves are slightly long.", 'bullets': ['Give your review a clear title and a star rating out of 5.', 'Explain why you bought the jacket and how well it performed in heavy rain and wind.', 'Mention one minor downside (such as the sleeve length or stiff main zip at first).', 'State clearly whether the jacket is good value for £45 and who you recommend it to.'], 'strategy': 'Use descriptive adjectives, honest pros and cons, and a helpful closing verdict.'}, {'format_idx': 8, 'format_name': 'Online Feedback Form', 'question_num': 1, 'marks': 15, 'word_count': '100–160 words', 'topic': 'Late Grocery Home Delivery with Missing Frozen Items', 'audience': 'Customer Care Team at FreshMart Supermarket', 'specialist_words': ['delivery', 'order number', 'frozen', 'missing', 'refund', 'substitutions', 'driver', 'time slot', 'apology', 'voucher'], 'stimulus': 'Order Note: Your FreshMart online food shop (Order #FM-3092, booked for Thursday 6:00pm–7:00pm) arrived at 9:15pm. Three bags of frozen vegetables were missing even though you were charged £8.50 for them.', 'bullets': ['Complete the Customer Name, Order Number (#FM-3092), Date, and Service Rating (2/5) at the top.', 'Explain that the delivery arrived over two hours late at 9:15pm without a phone call or text message.', 'State clearly which items were missing (£8.50 of frozen items) and request an immediate refund plus your £4.50 delivery fee back.'], 'strategy': 'Fill in all top form fields and write clear, polite full sentences explaining the fault and refund needed.'}, {'format_idx': 8, 'format_name': 'Online Feedback Form', 'question_num': 2, 'marks': 15, 'word_count': '100–160 words', 'topic': 'Patient Feedback on a Dental Check-Up & Helpful Receptionist', 'audience': 'Practice Manager at Parkside Dental Clinic', 'specialist_words': ['appointment', 'receptionist', 'nervous', 'reassuring', 'hygienist', 'waiting room', 'parking', 'polite', 'clean', 'satisfied'], 'stimulus': 'Visit Note: You attended Parkside Dental Clinic on Wednesday 21 October for a 10:00am check-up. You were nervous, but receptionist Priya and the dentist put you completely at ease. However, the waiting room was cold and the bike rack outside was full.', 'bullets': ['Fill in the Patient Name, Appointment Date, and Overall Rating (4/5 Stars).', 'Praise the spotless waiting room and how kind and reassuring Priya and the dentist were during your check-up.', 'Suggest one small improvement (fixing the waiting room heater and adding extra cycle spaces outside).'], 'strategy': 'Write in complete sentences inside each feedback section, balancing warm praise with a helpful suggestion.'}, {'format_idx': 9, 'format_name': 'Online Forum / Blog Post', 'question_num': 1, 'marks': 15, 'word_count': '110–170 words', 'topic': 'Should Public Parks Have Separate Fenced Areas for Dogs?', 'audience': "Local residents on the 'Greenwood Town Talk' online forum", 'specialist_words': ['owners', 'fenced', 'children', 'picnic', 'leads', 'exercise', 'safe', 'fouling', 'bins', 'respectful'], 'stimulus': "Forum Thread by @ParkRunner_Dan: 'Last weekend two off-lead dogs ran straight through our family picnic and knocked over a toddler. Dogs should be banned from the main park lawns!' Reply to the forum thread.", 'bullets': ['Include a forum username header and reply politely to @ParkRunner_Dan.', 'Show that you understand why families with young children and runners want safe, clean grass areas.', 'Suggest a fair compromise (creating a fenced dog exercise meadow and keeping dogs on leads near the play area and café).', 'Finish with a friendly question asking other residents what they think.'], 'strategy': 'Keep your tone polite and conversational while using accurate punctuation and paragraphs.'}, {'format_idx': 9, 'format_name': 'Online Forum / Blog Post', 'question_num': 2, 'marks': 15, 'word_count': '110–170 words', 'topic': 'Blog Post: My First Month Commuting to Work by Bike Instead of Car', 'audience': 'Readers of a local health and everyday lifestyle blog', 'specialist_words': ['commute', 'traffic', 'petrol', 'energetic', 'canal path', 'pannier bag', 'waterproof', 'fitness', 'money', 'habit'], 'stimulus': 'Blog Prompt: Write a short, friendly blog post sharing how you swapped driving in rush-hour traffic for a 20-minute cycle along the canal path to work every morning.', 'bullets': ['Write a catchy blog title and opening line about why you decided to leave the car at home.', 'Describe the best parts of cycling to work (saving £30 a week on petrol, avoiding traffic jams, and arriving wide awake).', 'Share two honest beginner tips (packing a waterproof coat and keeping spare work shoes under your desk).', 'End by asking readers how they travel to work or college.'], 'strategy': "Write in a warm first-person voice ('I') with clear paragraphs and an interactive closing question."}, {'format_idx': 10, 'format_name': 'Newsletter', 'question_num': 1, 'marks': 15, 'word_count': '130–190 words', 'topic': 'Riverside Sports & Social Club Monthly Member Newsletter', 'audience': 'Club members and local families', 'specialist_words': ['tournament', 'trophy', 'refurbished', 'badminton', 'quiz night', 'tickets', 'refreshments', 'volunteers', 'members', 'welcome'], 'stimulus': 'Club Notes: Write the November issue of the Riverside Club Newsletter celebrating the five-a-side football team winning the town cup, announcing the new Thursday evening beginner badminton sessions (£3 entry), and promoting the Charity Quiz Night on Saturday 28 November.', 'bullets': ['Include a bold Newsletter Masthead Banner with the issue month.', 'Congratulate the five-a-side football team on winning the Town Cup final.', 'Give full details of the new Thursday beginner badminton sessions (7:00pm–8:30pm, £3 per person, rackets provided).', "Include a 'Dates for Your Diary' section for the Saturday 28 November Charity Quiz Night and how to book a table."], 'strategy': 'Use a newsletter title banner, short section subheadings, exact times/prices, and a friendly sign-off.'}, {'format_idx': 10, 'format_name': 'Newsletter', 'question_num': 2, 'marks': 15, 'word_count': '130–190 words', 'topic': 'Oakwood Primary Parent & Carer Book Fair Newsletter', 'audience': 'Parents, carers, and school staff', 'specialist_words': ['reading', 'book fair', 'vouchers', 'storytelling', 'donations', 'library', 'children', 'volunteers', 'authors', 'assembly'], 'stimulus': "School Group Notes: Produce the monthly Parent & Carer Newsletter announcing next week's Autumn Book Fair in the Main Hall (Monday to Wednesday, 3:15pm–4:30pm), thanking families who donated 120 second-hand storybooks, and asking for three parent helpers.", 'bullets': ['Create a welcoming Newsletter Header and issue date.', 'Thank parents and carers for donating 120 pre-loved books for the school library.', 'Give the exact days, times, and half-price book voucher details for the Autumn Book Fair.', 'Explain how parents can volunteer to help run the book stalls after school.'], 'strategy': 'Organise with clear subheadings, warm community tone, and accurate punctuation.'}, {'format_idx': 11, 'format_name': 'Diary / Learning Log', 'question_num': 1, 'marks': 15, 'word_count': '110–170 words', 'topic': 'Learning Log: Practical Food Hygiene & Baking Session in the Catering Kitchen', 'audience': 'Your hospitality course tutor', 'specialist_words': ['apron', 'temperature', 'cross-contamination', 'chopping board', 'oven', 'timing', 'confidence', 'hygiene', 'recipe', 'target'], 'stimulus': 'Course Log Prompt: Write your weekly reflective learning log after completing your first practical catering session making vegetable soup and bread rolls in the college training kitchen.', 'bullets': ['Include the Date, Learner Name, and Session Title at the top.', 'Describe the food hygiene rules you followed (washing hands, wearing a clean apron, and using the green chopping board for vegetables).', 'Explain what went well and one thing you found tricky (such as kneading the bread dough or watching the oven timer).', "Set one clear target for next week's kitchen session."], 'strategy': "Write in the first person ('I'), explain what you learned, and finish with a clear target."}, {'format_idx': 11, 'format_name': 'Diary / Learning Log', 'question_num': 2, 'marks': 15, 'word_count': '110–170 words', 'topic': 'Learning Log: Assisting Visitors at the Community Library Help Desk', 'audience': 'Your volunteer coordinator', 'specialist_words': ['scanner', 'catalogue', 'printer', 'patient', 'enquiries', 'membership', 'computer', 'helpful', 'organized', 'independent'], 'stimulus': 'Placement Log Prompt: You completed your second four-hour shift volunteering at the Community Library Help Desk. You helped three new members register for library cards and showed an older visitor how to print a train ticket.', 'bullets': ['Write a clear Date and Placement Header at the top of your log.', 'Describe the tasks you completed on the help desk and how you spoke politely to visitors.', "Explain a problem you solved with your supervisor's help (clearing a paper jam in the public printer).", "State your personal learning goal for next Saturday's shift."], 'strategy': 'Use chronological paragraphs, honest first-person reflection, and accurate spelling.'}, {'format_idx': 12, 'format_name': 'Speech / Presentation Talk', 'question_num': 1, 'marks': 21, 'word_count': '150–250 words', 'topic': 'Workplace Team Talk: Using the Refurbished Staff Breakroom & Shift Swap Board', 'audience': 'Your retail store colleagues at the morning team huddle', 'specialist_words': ['breakroom', 'lockers', 'noticeboard', 'shift swap', 'microwave', 'tidy', 'colleagues', 'fair', 'manager', 'questions'], 'stimulus': "Team Talk Brief: Your store's refurbished staff breakroom opens today with new personal lockers, a hot water tap, and a new 'Shift Swap Noticeboard'. Give a short 3-minute talk to your team explaining how to keep the room clean and how to request shift swaps properly.", 'bullets': ["Greet your colleagues warmly ('Good morning everyone,') and introduce the topic of your talk.", 'Highlight the new breakroom features and explain the simple rules for keeping the fridge and sink clean.', 'Explain step by step how staff can swap weekend shifts using the new Shift Swap Board (getting manager sign-off 48 hours in advance).', 'Thank everyone for listening and ask if anyone has any questions.'], 'strategy': "Use spoken greeting, direct address ('you', 'we', 'our team'), clear signposts, and a thank-you close."}, {'format_idx': 12, 'format_name': 'Speech / Presentation Talk', 'question_num': 2, 'marks': 21, 'word_count': '150–250 words', 'topic': 'Community Centre Talk: Welcoming New Members to the Thursday Evening Art Group', 'audience': '15 beginners attending their first community art session', 'specialist_words': ['welcome', 'beginners', 'materials', 'watercolours', 'sketching', 'relaxed', 'tea break', 'exhibition', 'friendly', 'enjoy'], 'stimulus': 'Club Leader Brief: As coordinator of the Thursday Evening Community Art Group, welcome 15 new members to their first session, explain where aprons and paints are kept, and tell them about the Christmas Art Display.', 'bullets': ['Start with a warm welcome greeting and introduce yourself as the group coordinator.', 'Reassure beginners that no previous art experience is needed and explain where brushes, paper, and aprons are stored.', 'Mention the 7:30pm tea and biscuit break and invite everyone to take part in the December Community Art Display.', 'Finish with an encouraging closing line and thank everyone for coming.'], 'strategy': "Keep your spoken tone friendly, encouraging, and well-signposted ('First of all,', 'Next,', 'Finally,')."}]
